double midpoint_integration(FunctionPtr f, double a, double b, int N) {
    // Implementation of midpoint rule for numerical integration
    double h = (b - a) / N;  // width of each subinterval
    double integral = 0.0;

    for (int i = 0; i < N; i++) {
        double x_mid = a + (i + 0.5) * h;  // midpoint of the current subinterval
        integral += f(x_mid);
    }

    return h * integral;
}

